// Compare Monday against the ledger and work out what drifted.
// Nothing is deleted here — the worst this does is flag and re-sync.

const mondayItems = $('Pull Monday Board').first().json?.data?.boards?.[0]?.groups?.[0]?.items_page?.items || [];
const ledger = $input.all().map(i => i.json);

const col = (item, id) => (item.column_values.find(c => c.id === id)?.text || '').trim();

const byTicket = {};
for (const it of mondayItems) {
  const tid = col(it, 'text_mm5vaz0');
  if (tid) byTicket[tid] = { id: it.id, name: it.name, status: col(it, 'project_status'), severity: col(it, 'color_mm5vz074') };
}

const missingFromMonday = [];   // in the ledger, not on the board — needs re-pushing
const closedInMonday = [];      // marked Done on the board — close it in the ledger
const severityDrift = [];       // Brian changed severity on the board — ledger should follow

for (const t of ledger) {
  const m = byTicket[t.ticket_id];
  if (!m) { missingFromMonday.push(t); continue; }
  if (m.status === 'Done') closedInMonday.push({ ...t, monday_item_id: m.id });
  else if (m.severity && m.severity !== t.severity) severityDrift.push({ ...t, new_severity: m.severity, monday_item_id: m.id });
}

const orphans = mondayItems
  .filter(it => !col(it, 'text_mm5vaz0'))
  .map(it => ({ id: it.id, name: it.name }));

const stale = ledger.filter(t =>
  (t.severity === 'Show-stopper' && t.age_days >= 1) ||
  (t.severity === 'Fix before next use' && t.age_days >= 7) ||
  (!['Show-stopper','Fix before next use'].includes(t.severity) && t.age_days >= 30)
);

return [{ json: {
  open_count: ledger.length,
  missingFromMonday, closedInMonday, severityDrift, orphans, stale,
  drift_count: missingFromMonday.length + closedInMonday.length + severityDrift.length + orphans.length,
  by_venue: ledger.reduce((a, t) => { a[t.venue || 'Unknown'] = (a[t.venue || 'Unknown'] || 0) + 1; return a; }, {}),
  by_severity: ledger.reduce((a, t) => { a[t.severity || 'Untriaged'] = (a[t.severity || 'Untriaged'] || 0) + 1; return a; }, {})
} }];

parameters.query:
UPDATE tickets SET status = 'resolved', resolved_at = now(), resolution = 'Marked Done on the Monday board'
WHERE ticket_id = ANY($1::text[]);
UPDATE tickets t SET severity = d.sev
FROM (SELECT unnest($2::text[]) AS tid, unnest($3::text[]) AS sev) d
WHERE t.ticket_id = d.tid;
INSERT INTO ticket_events (ticket_id, actor, event, detail)
SELECT unnest($1::text[]), 'reconcile', 'resolved', '{"source":"monday"}'::jsonb;

