={{ (() => {
  const r = $('Reconcile').first().json;
  const sevLine = Object.entries(r.by_severity).map(([k,v]) => `${v} ${k.toLowerCase()}`).join(' · ') || 'nothing open';
  const venueLine = Object.entries(r.by_venue).sort((a,b)=>b[1]-a[1]).map(([k,v]) => `${k}: ${v}`).join('  ·  ') || '—';
  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: `:clipboard: Gear tickets — ${r.open_count} open`, emoji: true } },
    { type: 'section', text: { type: 'mrkdwn', text: `*${sevLine}*\n${venueLine}` } }
  ];
  if (r.stale.length) {
    blocks.push({ type: 'divider' });
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Been sitting a while:*\n' + r.stale.slice(0,8).map(t => `• _${t.age_days}d_ — ${t.title} (${t.venue})`).join('\n') } });
  }
  if (r.drift_count) {
    const bits = [];
    if (r.closedInMonday.length) bits.push(`closed ${r.closedInMonday.length} that you marked Done`);
    if (r.severityDrift.length) bits.push(`matched ${r.severityDrift.length} severity change${r.severityDrift.length===1?'':'s'}`);
    if (r.missingFromMonday.length) bits.push(`*${r.missingFromMonday.length} missing from the board* — needs a re-push`);
    if (r.orphans.length) bits.push(`${r.orphans.length} item${r.orphans.length===1?'':'s'} on the board with no ticket ID`);
    blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ':gear: ' + bits.join(' · ') }] });
  }
  return JSON.stringify({ blocks });
})() }}
